const server=createServer(async(req,res)=>{try{let url=new URL(req.url,origin);if(url.pathname==='/tone.wav'){const match=/bytes=(\d+)-(\d*)/.exec(req.headers.range||'');if(match){const start=Number(match[1]),end=Math.min(tone.length-1,match[2]?Number(match[2]):tone.length-1);res.writeHead(206,{'Content-Type':'audio/wav','Content-Length':end-start+1,'Content-Range':`bytes ${start}-${end}/${tone.length}`,'Accept-Ranges':'bytes','Access-Control-Allow-Origin':'*'});res.end(tone.subarray(start,end+1));return}res.writeHead(200,{'Content-Type':'audio/wav','Content-Length':tone.length,'Accept-Ranges':'bytes','Access-Control-Allow-Origin':'*'});res.end(tone);return}let filename=path.resolve('dist','.'+decodeURIComponent(url.pathname));if(!filename.startsWith(path.resolve('dist')+path.sep))filename=path.resolve('dist/index.html');try{if(!(await stat(filename)).isFile())filename=path.resolve('dist/index.html')}catch{filename=path.resolve('dist/index.html')}const data=await readFile(filename);res.writeHead(200,{'Content-Type':mime[path.extname(filename)]||'application/octet-stream'});res.end(data)}catch{res.writeHead(500);res.end()}})
await new Promise(resolve=>server.listen(4175,'127.0.0.1',resolve))
