 async function touchDrag(pg,handle,target){
  await handle.scrollIntoViewIfNeeded();const session=await pg.context().newCDPSession(pg),start=await handle.boundingBox();let x=start.x+start.width/2,y=start.y+start.height/2
  const send=type=>session.send('Input.dispatchTouchEvent',{type,touchPoints:type==='touchEnd'?[]:[{x,y,id:1,radiusX:5,radiusY:5,force:1}]})
  await send('touchStart');y+=8;await send('touchMove');await pg.waitForTimeout(100);await pg.locator('.music-drag-preview').waitFor()
  let box=await target.boundingBox();const height=await pg.evaluate(()=>innerHeight)
  for(let i=0;i<18&&(box.y<120||box.y+box.height>height-110);i++){y=box.y<120?15:height-15;await send('touchMove');await pg.waitForTimeout(120);box=await target.boundingBox()}
  assert.ok(box.y>=0&&box.y<height,'Destino visível após rolagem do arraste');const endX=box.x+Math.min(80,box.width/2),endY=box.y+5,sx=x,sy=y
  for(let i=1;i<=12;i++){x=sx+(endX-sx)*i/12;y=sy+(endY-sy)*i/12;await send('touchMove');await pg.waitForTimeout(20)}
  for(let i=0;i<8;i++){
   const hit=await pg.evaluate(({x,y})=>document.elementFromPoint(x,y)?.closest('.playlist-tracks,.queue-dialog')?.getAttribute('aria-label'),{x,y}),dest=await target.evaluate(el=>el.closest('.playlist-tracks,.queue-dialog')?.getAttribute('aria-label'))
   if(hit===dest)break
   box=await target.boundingBox();x=box.x+Math.min(80,box.width/2);y=box.y+Math.min(24,box.height/2);await send('touchMove');await pg.waitForTimeout(100)
  }
  await pg.waitForTimeout(80);
  const drop=await pg.evaluate(({x,y})=>({hit:document.elementFromPoint(x,y)?.closest('.playlist-tracks,.queue-dialog')?.getAttribute('aria-label'),tag:document.elementFromPoint(x,y)?.className}),{x,y}),destination=await target.evaluate(el=>el.closest('.playlist-tracks,.queue-dialog')?.getAttribute('aria-label'));assert.equal(drop.hit,destination,'Soltar sobre a lista de destino: '+JSON.stringify(drop));
  await send('touchEnd');await pg.locator('.music-drag-preview').waitFor({state:'hidden'});await session.detach();await pg.waitForTimeout(200)
 }
